# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "tool forms": result views that show the inputs of the agent tool that made them, to
#          change and run again; the Results tab bar's "+" adds one by hand. Generic: a form is
#          built from a tool's parameter schema, the very one pydantic-ai gives the model (names,
#          types, defaults, choices, descriptions), and its values are checked by the tool's own
#          argument validator, so a form can't drift from its tool. Which inputs made a result is
#          recorded by the session (Session.calls), not read off the result.
#          Which widgets have one is in widgets.py (Widget.tool); this file is the generic part.
#          A form is also what the widget inline chat fills (inline_fill.py): fill_schema is the
#          AI's output shape, check its validation, texts the values as the form shows them.
# ---------------------------------------------------------------------------
from __future__ import annotations

import dataclasses
import enum
import typing
from functools import cached_property
from typing import TYPE_CHECKING, Any, Literal

from ds.data.chars import CharEnum
from pydantic import ValidationError
from pydantic_ai import Tool

if TYPE_CHECKING:
    from collections.abc import Callable


@dataclasses.dataclass
class FormField:
    """One tool parameter as the browser shows it."""

    name: str
    label: str
    kind: str = "text"
    """text | number | select | check | choice (a character enum or list[<a fixed set of
    values>], see picker_for)"""
    value: str = ""
    options: list[str] = dataclasses.field(default_factory=list)
    """select only; "" means not set."""
    help: str = ""
    """The parameter's description from the tool's schema, shown as the field's tooltip."""
    choices: list[dict[str, str]] = dataclasses.field(default_factory=list)
    """choice only: every option as value, label, icon (a path under pkgs/ds/data/; "" when
    the options have none). A choice field's `value` is the picked values joined by ","."""
    multiple: bool = False
    """choice only: several picks (a list parameter), else one. The only difference between the two."""
    search: bool = False
    """choice only: the options are many (over CHOICE_SEARCH_AT), so the list gets a search box,
    single or multiple alike."""
    changed: bool = False
    """The inline chat proposed this value and it differs from the one that made the result
    (highlighted; `help` then starts with the old value)."""

    def __setstate__(self, state: dict[str, Any]) -> None:
        # kept in Reflex's on-disk state (inside a ViewData): one saved before `changed` existed
        self.__dict__.update({"changed": False} | state)


# A choice input with more options than this gets a search box above its list.
CHOICE_SEARCH_AT = 8


def _option_choices(item: Any) -> list[tuple[str, Any, str, str]] | None:
    """(text, value, label, icon) for each value of a fixed-set type: a ds.data.CharEnum (with
    its display names and icons), another Enum, or a Literal; None for any other type."""
    if isinstance(item, type) and issubclass(item, CharEnum):
        return [(c.value, item(c.value), c.label, c.icon) for c in item.choices()]
    if isinstance(item, type) and issubclass(item, enum.Enum):
        return [(str(m.value), m, str(m.value), "") for m in item]
    if typing.get_origin(item) is Literal:
        return [(str(arg), arg, str(arg), "") for arg in typing.get_args(item)]
    return None


@dataclasses.dataclass(frozen=True)
class Picker:
    """A parameter the form shows as the pick-from-a-list input (render._choice_input)."""

    options: list[tuple[str, Any, str, str]]
    """(text, value, label, icon) per option, see _option_choices"""
    multiple: bool
    """a list parameter: several picks; else one"""


def picker_for(hint: Any) -> Picker | None:
    """The pick-from-a-list input for a parameter's type (also `T | None`), else None:
    - a character enum (ds.data.CharEnum, eg CharGroup): one pick
    - `list[T]`, T a character enum, another Enum or a Literal: several picks
    The type decides, not the parameter's name, so any tool gets the same input. (A single
    Enum / Literal stays a dropdown: its options are few and have no icons.)"""
    for arg in [hint, *typing.get_args(hint)]:
        if typing.get_origin(arg) is list and (items := typing.get_args(arg)):
            options = _option_choices(items[0])
            return Picker(options, multiple=True) if options is not None else None
        if isinstance(arg, type) and issubclass(arg, CharEnum):
            return Picker(_option_choices(arg) or [], multiple=False)
    return None


def _picked(value: Any) -> list[str]:
    """A choice field's picked values as text: from the tool's own inputs (eg CharGroup.STEVE
    or [CharGroup.STEVE]) or the form's submitted "steve,pac_man"."""
    if value is None or value == "":
        return []
    items = value.split(",") if isinstance(value, str) else value
    return [str(item.value if isinstance(item, enum.Enum) else item).strip() for item in items if str(item).strip()]


def schema_fields(schema: dict[str, Any], values: dict[str, Any], hide: tuple[str, ...] = ()) -> list[FormField]:
    """Form fields for a JSON schema's properties (an object schema, as pydantic makes for a
    function's parameters or a model), filled from values, else each property's default.

    string -> text, integer / number -> number, boolean -> check, a fixed set of values (enum /
    const, also inside anyOf) -> select. Anything else is a text box.
    """
    fields = []
    for name, prop in schema.get("properties", {}).items():
        if name in hide:
            continue
        options = _choices(prop)
        kind = (
            "select"
            if options
            else {"integer": "number", "number": "number", "boolean": "check"}.get(prop.get("type", ""), "text")
        )
        value = values.get(name, prop.get("default", ""))
        fields.append(
            FormField(
                name=name,
                label=name.replace("_", " "),
                kind=kind,
                value="on" if value is True else "" if value in (None, False) else str(value),
                # "not set" first
                options=sorted(options, key=bool),
                help=" ".join(str(prop.get("description", "")).split()),
            )
        )
    return fields


def _choices(prop: dict[str, Any]) -> list[str]:
    """A property's fixed set of values ([] if it is free): enum / const, directly or in every anyOf branch."""
    branches = prop.get("anyOf") or [prop]
    options: list[str] = []
    for branch in branches:
        if "enum" in branch:
            options += [str(option) for option in branch["enum"]]
        elif "const" in branch:
            options.append(str(branch["const"]))
        else:
            return []
    return options


def _choice_value(prop: dict[str, Any], text: str) -> Any:
    """The choice a select submitted, as its real value: a form sends "60", the tool's
    Literal[30, 60, ...] wants 60 (pydantic doesn't turn text into a Literal number)."""
    for branch in prop.get("anyOf") or [prop]:
        for option in branch.get("enum", [branch["const"]] if "const" in branch else []):
            if str(option) == text:
                return option
    return text


@dataclasses.dataclass
class ToolRequest:
    """A tool form not run yet (added with "+"): a placeholder value shown as just the form.
    Running it replaces it with the tool's result."""

    form: str
    """The ToolForm's key."""
    inputs: dict[str, Any] = dataclasses.field(default_factory=dict)


@dataclasses.dataclass
class ToolForm:
    title: str
    """What the "+" menu calls it, eg 'Match videos'."""
    function: Callable[..., Any]
    """The agent's tool function. Its return annotation is the result type that gets the form."""
    hide: tuple[str, ...] = ()
    """Parameters not on the form (they keep their defaults), eg paging the view does itself."""

    # ds::exception: caching (approved 2026-11-15): from the tool function's signature, which
    #   only changes with a code edit
    @cached_property
    def tool(self) -> Tool:
        return Tool(self.function)

    @property
    def key(self) -> str:
        return self.tool.name

    # ds::exception: caching (approved 2026-11-15): from the tool function's signature, which
    #   only changes with a code edit
    @cached_property
    def schema(self) -> dict[str, Any]:
        """The parameters' JSON schema, as the model gets it."""
        return self.tool.tool_def.parameters_json_schema

    # ds::exception: caching (approved 2026-11-15): from the tool function's signature, which
    #   only changes with a code edit
    @cached_property
    def result_type(self) -> type:
        return typing.get_type_hints(self.function)["return"]

    # ds::exception: caching (approved 2026-11-15): from the tool function's signature, which
    #   only changes with a code edit
    @cached_property
    def pickers(self) -> dict[str, Picker]:
        """Parameters shown as the pick-from-a-list input: name -> its Picker (see picker_for)."""
        hints = typing.get_type_hints(self.function)
        return {name: found for name, hint in hints.items() if (found := picker_for(hint)) is not None}

    def fields(self, values: dict[str, Any]) -> list[FormField]:
        fields = schema_fields(self.schema, values, self.hide)
        for field in fields:
            if picker := self.pickers.get(field.name):
                field.kind, field.multiple = "choice", picker.multiple
                field.search = len(picker.options) > CHOICE_SEARCH_AT
                field.choices = [
                    {"value": text, "label": label, "icon": icon} for text, _, label, icon in picker.options
                ]
                field.value = ",".join(_picked(values.get(field.name, field.value)))
        return fields

    @property
    def description(self) -> str:
        """What the tool does and what each input means: its docstring, as the model gets it."""
        return self.tool.tool_def.description or ""

    @property
    def fill_schema(self) -> dict[str, Any]:
        """The schema of the inputs on the form (the tool's, without the hidden parameters):
        what the widget inline chat's AI answers with (inline_fill.py)."""
        shown = {name: prop for name, prop in self.schema.get("properties", {}).items() if name not in self.hide}
        required = [name for name in self.schema.get("required", []) if name in shown]
        return {**self.schema, "properties": shown, "required": required}

    def check(self, given: dict[str, Any]) -> dict[str, Any]:
        """Typed values as the tool's arguments, checked by the validator pydantic-ai uses for the
        model's calls (hidden parameters are dropped: they keep their defaults). Raises ValueError
        naming the bad fields."""
        given = {name: value for name, value in given.items() if name not in self.hide}
        try:
            return self.tool.function_schema.validator.validate_python(given)
        except ValidationError as error:
            problems = [f"{'.'.join(map(str, e['loc']))}: {e['msg']}" for e in error.errors()]
            raise ValueError("; ".join(problems)) from error

    def texts(self, values: dict[str, Any]) -> dict[str, str]:
        """Each input on the form as the text its field shows for these values (typed arguments,
        or a submitted form): what a form submits, so two sets of inputs can be compared."""
        return {field.name: field.value for field in self.fields(values)}

    def arguments(self, raw: dict[str, Any]) -> dict[str, Any]:
        """A submitted form as the tool's arguments, checked by the validator pydantic-ai uses for
        the model's calls. Raises ValueError naming the bad fields."""
        given: dict[str, Any] = {}
        for name, prop in self.schema.get("properties", {}).items():
            if name in self.hide:
                continue
            value = raw.get(name, "")
            if picker := self.pickers.get(name):
                # "steve,pac_man" -> the typed values the tool wants (an unknown one stays text,
                # so the validator names it); nothing picked = the default
                by_text = {text: typed for text, typed, _, _ in picker.options}
                if picked := [by_text.get(text, text) for text in _picked(value)]:
                    given[name] = picked if picker.multiple else picked[0]
            elif prop.get("type") == "boolean":
                # an unticked checkbox is missing from (or falsy in) the submitted form
                given[name] = value not in ("", None, False, "false", "off")
            elif isinstance(value, str) and prop.get("type") != "string" and not _choices(prop):
                if value.strip():  # an empty number box = the default
                    given[name] = value.strip()
            elif value == "" and (choices := _choices(prop)) and "" not in choices:
                continue  # a select left out of the submitted inputs = the default
            elif isinstance(value, str) and _choices(prop):
                given[name] = _choice_value(prop, value.strip())
            else:
                given[name] = value.strip() if isinstance(value, str) else value
        return self.check(given)

    def run(self, raw: dict[str, Any]) -> tuple[Any, dict[str, Any]]:
        """Run the tool with a submitted form: (its result, the inputs used, for Session.calls)."""
        arguments = self.arguments(raw)
        shown = {name: value for name, value in arguments.items() if name not in self.hide}
        return self.function(**arguments), shown
